def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []

    # Find the blank centers of the plus-shaped arrangements of 2s.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r-1][c] == 2 and
                grid[r+1][c] == 2 and grid[r][c-1] == 2 and
                grid[r][c+1] == 2):
                centers.append((r, c))

    # Connect only consecutive motifs along each row or column.
    for r in range(h):
        row_centers = sorted(c for rr, c in centers if rr == r)
        for a, b in zip(row_centers, row_centers[1:]):
            for c in range(a + 2, b - 1):
                if out[r][c] == 0:
                    out[r][c] = 1

    for c in range(w):
        col_centers = sorted(r for r, cc in centers if cc == c)
        for a, b in zip(col_centers, col_centers[1:]):
            for r in range(a + 2, b - 1):
                if out[r][c] == 0:
                    out[r][c] = 1

    return out
